#!/bin/bash
# Build 24: upstream nx2 794602bf with #313, the unbacked image fix and 128 query banks.
set -eux
UP=${UPSTREAM:-https://github.com/zortos293/lichii}
if [ -z "${LOCAL_ONLY:-}" ]; then
  git fetch -q "$UP" 794602bfbd012ac59dc1c8a1c9ceb8e5ddc99a3b
fi
git checkout -q --detach 794602bfbd012ac59dc1c8a1c9ceb8e5ddc99a3b
echo "" | base64 -d | xz -d > "${RUNNER_TEMP:-/tmp}/b24.diff"
git apply --index "${RUNNER_TEMP:-/tmp}/b24.diff"
git commit -q -m "Build 24 changes: PR #313, unbacked image fix (e15125b), 128 query banks"
test "$(git rev-parse 'HEAD^{tree}')" = ec2dc96449c8bd15f0b8beae11c3546ba1ace1b9
for f in $(git ls-tree -r --name-only HEAD .github); do
  git cat-file -e "fork_tip:$f" 2>/dev/null || git rm -q "$f"
done
git checkout fork_tip -- .github
git commit -q -m "Keep this fork's workflow files" || true
test -z "$(git diff fork_tip HEAD -- .github)"
TREE=$(git rev-parse 'HEAD^{tree}')
echo "final tree $TREE"
NEW=$(git commit-tree "$TREE" -p fork_tip -p HEAD -m "Build 24: upstream nx2 794602bf (OoT water texture fix #778, movie network #721) with #313, the unbacked image fix and 128 query banks")
git checkout -q --detach "$NEW"
